document.addEventListener("DOMContentLoaded",function(){var t=document.querySelector(".nav-toggle"),n=document.querySelector(".nav-menu");t&&n&&(t.addEventListener("click",function(){n.classList.toggle("active");var e=t.querySelectorAll("span");n.classList.contains("active")?(e[0].style.transform="rotate(45deg) translate(5px, 5px)",e[1].style.opacity="0",e[2].style.transform="rotate(-45deg) translate(7px, -6px)"):(e[0].style.transform="none",e[1].style.opacity="1",e[2].style.transform="none")}),n.querySelectorAll(".nav-link").forEach(function(e){e.addEventListener("click",function(){n.classList.remove("active");var e=t.querySelectorAll("span");e[0].style.transform="none",e[1].style.opacity="1",e[2].style.transform="none"})})),document.querySelectorAll('a[href^="#"]').forEach(function(e){e.addEventListener("click",function(e){var t=this.getAttribute("href");"#"!==t&&1<t.length&&(e.preventDefault(),e=document.querySelector(t))&&e.scrollIntoView({behavior:"smooth",block:"start"})})})});